const item = $input.first();
const binary = item.binary?.data;

if (!binary) {
  return [{ json: { ...item.json, file_type: 'unsupported', original_filename: item.json.name || 'unknown' } }];
}

const fileName = binary.fileName || item.json.name || 'unknown';
const mimeType = (binary.mimeType || '').toLowerCase();
const ext = (fileName.split('.').pop() || '').toLowerCase();

let file_type = 'unsupported';
if (ext === 'pdf' || mimeType === 'application/pdf') {
  file_type = 'pdf';
} else if (ext === 'docx' || mimeType.includes('officedocument.wordprocessingml')) {
  file_type = 'docx';
} else if (ext === 'doc' || mimeType === 'application/msword') {
  file_type = 'doc';
} else if (ext === 'txt' || mimeType.startsWith('text/plain')) {
  file_type = 'txt';
}

return [{
  json: { ...item.json, file_type, original_filename: fileName },
  binary: item.binary
}];

const item = $input.first();
const { text: rawText, ...rest } = item.json;
const text = (rawText || '').trim();

return [{
  json: { ...rest, raw_text: text, is_scanned: text.length < 100 },
  binary: $('Detect File Type').item.binary
}];

const zlib = require('zlib');
const item = $input.first();
const buffer = Buffer.from(item.binary.data.data, 'base64');

// Minimal ZIP reader to pull word/document.xml out of the .docx package
function readZipEntry(buf, entryName) {
  const eocdSig = 0x06054b50;
  let eocdOffset = -1;
  for (let i = buf.length - 22; i >= 0; i--) {
    if (buf.readUInt32LE(i) === eocdSig) { eocdOffset = i; break; }
  }
  if (eocdOffset === -1) throw new Error('Not a valid DOCX (zip) file');

  const cdEntries = buf.readUInt16LE(eocdOffset + 10);
  let offset = buf.readUInt32LE(eocdOffset + 16);

  for (let i = 0; i < cdEntries; i++) {
    if (buf.readUInt32LE(offset) !== 0x02014b50) break;
    const compMethod = buf.readUInt16LE(offset + 10);
    const compSize = buf.readUInt32LE(offset + 20);
    const nameLen = buf.readUInt16LE(offset + 28);
    const extraLen = buf.readUInt16LE(offset + 30);
    const commentLen = buf.readUInt16LE(offset + 32);
    const localHeaderOffset = buf.readUInt32LE(offset + 42);
    const fileName = buf.toString('utf8', offset + 46, offset + 46 + nameLen);

    if (fileName === entryName) {
      const lfhNameLen = buf.readUInt16LE(localHeaderOffset + 26);
      const lfhExtraLen = buf.readUInt16LE(localHeaderOffset + 28);
      const dataStart = localHeaderOffset + 30 + lfhNameLen + lfhExtraLen;
      const compData = buf.subarray(dataStart, dataStart + compSize);
      return compMethod === 0 ? compData : zlib.inflateRawSync(compData);
    }

    offset += 46 + nameLen + extraLen + commentLen;
  }
  throw new Error(`Entry ${entryName} not found in DOCX`);
}

const xml = readZipEntry(buffer, 'word/document.xml').toString('utf8');

const text = xml
  .replace(/<\/w:p>/g, '\n')
  .replace(/<w:tab\s*\/>/g, '\t')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&apos;/g, "'")
  .trim();

return [{ json: { ...item.json, raw_text: text } }];

const item = $input.first();
const raw_text = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');

return [{ json: { ...item.json, raw_text } }];

const item = $input.first();
return [{
  json: {
    ...item.json,
    extraction_error: 'DOC (legacy binary Word) format requires LibreOffice conversion on the n8n host, which is not yet configured. Convert this file to .docx or .pdf and re-upload, or configure an Execute Command node running "libreoffice --headless --convert-to docx" and route its output into the DOCX extraction branch.'
  }
}];

const item = $input.first();
return [{
  json: {
    ...item.json,
    extraction_error: `Unsupported file type for "${item.json.original_filename || 'unknown file'}". Supported types: pdf, docx, doc, txt.`
  }
}];

const item = $input.first();
const response = item.json;
let text = '';

if (response.output_text) {
  text = response.output_text;
} else if (Array.isArray(response.output)) {
  for (const block of response.output) {
    if (Array.isArray(block.content)) {
      for (const c of block.content) {
        if (c.type === 'output_text' && c.text) text += c.text;
      }
    }
  }
}

return [{
  json: {
    ...$('Extract PDF').first().json,
    raw_text: text.trim()
  }
}];

const item = $input.first();
let text = item.json.raw_text || '';

const patterns = [
  /^\s*(Skip to (main )?content)\s*$/gim,
  /^\s*(Home|Menu|Navigation)\s*(\||>)\s*.*$/gim,
  /^\s*(Share|Tweet|Print|Email) this (page|article).*$/gim,
  /^\s*©\s*\d{4}.*$/gim,
  /^\s*(Follow us on|Find us on)\s+(Facebook|Twitter|Instagram|LinkedIn).*$/gim,
  /^\s*(Privacy Policy|Terms of (Use|Service)|Cookie Policy)\s*$/gim,
  /^\s*Page \d+ of \d+\s*$/gim
];

for (const pattern of patterns) {
  text = text.replace(pattern, '');
}

text = text.replace(/\n{3,}/g, '\n\n').trim();

return [{ json: { ...item.json, raw_text: text } }];

const item = $input.first();
const content = item.json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Clean stage returned no content. Response: ' + JSON.stringify(item.json).slice(0, 500));
}

return [{ json: { cleaned_text: content } }];

const item = $input.first();
const content = item.json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Classify stage returned no content. Response: ' + JSON.stringify(item.json).slice(0, 500));
}

let classification;
try {
  classification = JSON.parse(content);
} catch (e) {
  throw new Error(`Classify stage returned invalid JSON: ${e.message}. Content: ${content.slice(0, 500)}`);
}

const required = ['condition_title', 'document_type', 'audience_segments', 'clinical_figures', 'named_products'];
for (const key of required) {
  if (!(key in classification)) {
    throw new Error(`Classification JSON missing required field: ${key}`);
  }
}

return [{ json: classification }];

const item = $input.first();
const md = item.json.choices?.[0]?.message?.content;

if (!md) {
  throw new Error('Produce KB stage returned no content. Response: ' + JSON.stringify(item.json).slice(0, 500));
}

const classification = $('Parse Classification JSON').first().json;
const fallbackName = ($('Detect File Type').first().json.original_filename || 'document').replace(/\.[^.]+$/, '');
const baseName = (classification.condition_title || fallbackName)
  .replace(/[^a-zA-Z0-9 _-]/g, '')
  .trim()
  .replace(/\s+/g, '-');

return [{
  json: {
    kb_markdown: md,
    output_filename: `${baseName}.md`
  }
}];

const item = $input.first();
const j = item.json || {};

const errorMessage = j.error?.message || j.message || j.extraction_error || JSON.stringify(j).slice(0, 1000);
const filename = $('Detect File Type').first()?.json?.original_filename || 'unknown';

return [{
  json: {
    error_log: JSON.stringify({
      original_filename: filename,
      error_message: errorMessage,
      timestamp: new Date().toISOString()
    }, null, 2),
    error_filename: `${filename}.error.json`
  }
}];
